from __future__ import annotations

import hashlib
from dataclasses import dataclass


@dataclass
class Snapshot:
    text: str
    digest: str
    elements: dict


SNAPSHOT_JS = r"""({start, expanded}) => {
  const visible = e => { const r=e.getBoundingClientRect(),s=getComputedStyle(e);
    return r.width>0&&r.height>0&&s.visibility!=='hidden'&&s.display!=='none'; };
  const tidy = s => (s||'').replace(/[\u200B-\u200D\uFEFF]/g,'').replace(/\s+/g,' ').trim();
  let next=start;
  const elements=[];
  // Hidden controls retain attributes across redraws; clear the previous observation first.
  document.querySelectorAll('[data-rfq-observe]').forEach(e=>e.removeAttribute('data-rfq-observe'));
  const selector='a,button,input,select,textarea,summary,[role=button],[role=link],[role=tab],[role=menuitem],[role=option],[role=checkbox],[role=radio],[onclick],[tabindex]';
  for (const e of document.querySelectorAll(selector)) {
    if(!visible(e)||e.getAttribute('type')==='hidden') continue;
    const id=next++; e.setAttribute('data-rfq-observe',String(id));
    let label=e.getAttribute('aria-label')||'';
    if(e.labels&&e.labels.length) label=Array.from(e.labels).map(l=>tidy(l.innerText)).join(' ');
    label=label||tidy(e.innerText)||e.getAttribute('placeholder')||e.getAttribute('title')||e.getAttribute('name')||'';
    const type=e.getAttribute('type')||e.getAttribute('role')||e.tagName.toLowerCase();
    const value=type==='password'?(e.value?'[secret]':''):('value' in e?e.value:'');
    const options=e.tagName==='SELECT'?Array.from(e.options).map(o=>({value:o.value,text:o.text})):undefined;
    const checked=typeof e.checked==='boolean'?e.checked:(['checkbox','radio'].includes(type)?e.getAttribute('aria-checked')==='true':undefined);
    const rect=e.getBoundingClientRect(), x=rect.x+rect.width/2, y=rect.y+rect.height/2;
    let obstruction='';
    if(x>=0&&y>=0&&x<innerWidth&&y<innerHeight){
      const top=document.elementFromPoint(x,y);
      if(top&&!e.contains(top)&&!top.contains(e)){
        const blocker=top.closest('dialog,[role=dialog],[aria-modal=true],section,aside')||top;
        obstruction=tidy(blocker.getAttribute('aria-label')||blocker.innerText||blocker.tagName).slice(0,180);
      }
    }
    elements.push({id,tag:e.tagName.toLowerCase(),type,label:label.slice(0,350),value,checked,
      obstruction,
      modal:!!e.closest('dialog[open],[role=dialog],[aria-modal=true]'),
      href:e.getAttribute('href')||undefined,options,disabled:e.matches(':disabled'),readonly:!!e.readOnly,min:e.min,max:e.max});
  }
  const dialogs=Array.from(document.querySelectorAll('dialog,[role=dialog],[aria-modal=true]')).filter(visible).map(e=>e.innerText);
  const sections=Array.from(document.querySelectorAll('h1,h2,h3,summary')).filter(visible).map(e=>tidy(e.innerText));
  const clone=document.body?.cloneNode(true);
  let nav='';
  if(clone){
    const originalNodes=Array.from(document.body.querySelectorAll('*'));
    const clonedNodes=Array.from(clone.querySelectorAll('*'));
    originalNodes.forEach((e,i)=>{
      const s=getComputedStyle(e),copy=clonedNodes[i];
      if(s.display==='none'||s.visibility==='hidden'){copy.remove();return;}
      if(['block','flex','grid','list-item','table-row','table-cell'].includes(s.display)){
        copy.before(document.createTextNode('\n'));copy.after(document.createTextNode('\n'));
      }
    });
    clone.querySelectorAll('br,hr').forEach(e=>e.replaceWith(document.createTextNode('\n')));
    clone.querySelectorAll('script,style,svg,noscript').forEach(e=>e.remove());
    clone.querySelectorAll('nav,header,footer').forEach(e=>{nav+=tidy(e.textContent)+'\n';e.remove();});
    clone.querySelectorAll('table').forEach(t=>{
      const rows=Array.from(t.querySelectorAll('tr')).map(r=>Array.from(r.querySelectorAll('th,td')).map(c=>tidy(c.textContent)).join(' | '));
      t.replaceWith(document.createTextNode('\n'+rows.join('\n')+'\n'));
    });
  }
  let body=(clone?.textContent||'').replace(/[\u200B-\u200D\uFEFF]/g,'').split('\n').map(s=>s.trim()).filter(Boolean).join('\n');
  if(expanded){const target=Array.from(document.querySelectorAll('h1,h2,h3,section,article,table')).find(e=>tidy(e.innerText).includes(expanded));if(target)body=target.innerText;}
  return {title:document.title,body,nav,dialogs,sections,elements,next};
}"""


async def settle(page):
    try:
        await page.wait_for_load_state("networkidle", timeout=1200)
    except Exception:
        pass
    try:
        await page.evaluate("""() => new Promise(resolve => {
          let quiet; const done=()=>{observer.disconnect();clearTimeout(quiet);resolve()};
          const observer=new MutationObserver(()=>{clearTimeout(quiet);quiet=setTimeout(done,150)});
          observer.observe(document,{subtree:true,childList:true,attributes:true});
          quiet=setTimeout(done,150);setTimeout(done,900);
        })""")
    except Exception:
        pass


async def observe(session, max_chars: int = 26000, expanded: str = "") -> Snapshot:
    await settle(session.page)
    pieces = [f"URL {session.page.url}"]
    elements = {}
    next_id = 1
    for index, frame in enumerate(session.page.frames):
        try:
            ancestor = frame
            visible = True
            while ancestor.parent_frame is not None:
                container = await ancestor.frame_element()
                if not await container.is_visible():
                    visible = False
                    break
                ancestor = ancestor.parent_frame
            if not visible:
                continue
            data = await frame.evaluate(SNAPSHOT_JS, {"start": next_id, "expanded": expanded})
        except Exception:
            continue
        next_id = data["next"]
        frame_path = f"frame/{index}"
        pieces.append(f"{frame_path}: {data['title']} ({frame.url})")
        if data["dialogs"]:
            pieces.append("DIALOGS\n" + "\n".join(data["dialogs"]))
        nav_hash = hashlib.sha256(data["nav"].encode()).hexdigest()
        if nav_hash not in session.nav_hashes:
            pieces.append("Navigation: " + data["nav"])
            session.nav_hashes.add(nav_hash)
        pieces.append(data["body"])
        pieces.append("CONTROLS")
        for e in data["elements"]:
            elements[e["id"]] = {**e, "frame": frame, "frame_path": frame_path}
            details = f"[{e['id']}] {e['type']} {e['label']}"
            if e.get("value"):
                details += f" value={e['value']}"
            if e.get("type") in ("checkbox", "radio"):
                details += " CHECKED" if e.get("checked") else " UNCHECKED"
            if e.get("type") == "range":
                details += f" min={e.get('min')} max={e.get('max')}"
            if e.get("modal"):
                details += " MODAL"
            if e.get("obstruction"):
                details += " OBSCURED by " + e["obstruction"]
            if e.get("options"):
                details += " options=" + str(e["options"])
            if e.get("href"):
                details += " href=" + e["href"]
            if e.get("disabled"):
                details += " DISABLED"
            if e.get("readonly"):
                details += " READONLY"
            pieces.append(details)
        pieces.append("Sections: " + " | ".join(data["sections"]))
    if session.notices:
        pieces.insert(0, "NOTICES\n" + "\n".join(session.notices))
        session.notices.clear()
    pieces.append("TABS " + " | ".join(f"{i}: {p.url}" for i, p in enumerate(session.context.pages)))
    text = "\n".join(pieces)
    if len(text) > max_chars:
        # Retain controls at the tail and provide explicit model-selected expansion.
        tail = "\n".join(p for p in pieces if p.startswith("[") or p.startswith("Sections:"))[-max_chars // 3:]
        text = text[:max_chars - len(tail) - 120] + "\n[TRUNCATED; expand a section heading or scroll]\n" + tail
    # Ignore transient control values only for navigation dedupe? No: all content matters.
    digest = hashlib.sha256(text.encode()).hexdigest()
    result = Snapshot(text, digest, elements)
    session.elements = elements
    session.last_snapshot = result
    return result

from __future__ import annotations

import asyncio
import re
from urllib.parse import urlsplit


def _origin(url):
    parts = urlsplit(url)
    return f"{parts.scheme}://{parts.netloc}"


async def consent(session):
    """Dismiss generic cookie consent using only consent-related page text."""
    for frame in session.page.frames:
        try:
            text = await frame.locator("body").inner_text(timeout=800)
            if len(text) > 3500 or not re.search(r"cookie|cookies|datenschutz|consent", text, re.I):
                continue
            button = frame.get_by_role("button", name=re.compile(r"(?:notwendige|necessary|essential).*cookies.*(?:akzeptieren|accept)|(?:alle akzeptieren|accept all|zustimmen)", re.I))
            if await button.count() == 1 and await button.is_visible():
                await button.click(timeout=3500)
                session.notices.append("Generic cookie consent accepted.")
                return
        except Exception:
            pass


async def login(session) -> str:
    """Fill a model-selected login form using generic credential field types."""
    for frame in session.page.frames:
        passwords = frame.locator('input[type="password"]:visible')
        if not await passwords.count():
            continue
        # An assigned worker may follow evidence to another run-provided site.
        site = getattr(session, "sites_by_origin", {}).get(_origin(frame.url),
                getattr(session, "current_site", session.site))
        credentials = site.get("credentials") or {}
        form = passwords.first.locator("xpath=ancestor::form[1]")
        scope = form if await form.count() else frame
        users = scope.locator('input:not([type="password"]):not([type="hidden"]):not([type="submit"]):not([type="checkbox"]):not([type="radio"]):not([readonly]):not([disabled]):visible')
        if not await users.count():
            return "Login needs a username field selected explicitly."
        await users.first.fill(credentials.get("username", ""))
        await passwords.first.fill(credentials.get("password", ""))
        await passwords.first.press("Enter")
        await asyncio.sleep(0.2)
        return "Login credentials entered; verify the next observation."
    return "No visible password form found."


async def recover(session, bus=None, agent=""):
    if session.page.is_closed():
        remaining = [page for page in session.context.pages if not page.is_closed()]
        if remaining:
            session.page = remaining[0]
            await session.page.bring_to_front()
        else:
            session.page = await session.context.new_page()
            session.install_handlers(session.page)
            await session.page.goto(session.last_good_url or session.site["url"], wait_until="domcontentloaded")
        session.notices.append("Selected tab closed; restored a remaining working tab.")
    await consent(session)
    # These are generic browser failure patterns, never site paths.
    text = ""
    try:
        text = await session.page.locator("body").inner_text(timeout=1200)
    except Exception:
        return
    if len(text) < 3000 and any(s in text.casefold() for s in ("service unavailable", "bad gateway", "temporarily unavailable")):
        for attempt in range(4):
            if bus:
                bus.emit("retry", agent, {"attempt": attempt + 1, "reason": "temporary page failure"})
            await asyncio.sleep(min(2 ** attempt, 8))
            await session.page.reload(wait_until="domcontentloaded")
            text = await session.page.locator("body").inner_text()
            if not any(s in text.casefold() for s in ("service unavailable", "bad gateway", "temporarily unavailable")):
                break
    # Reauthentication is allowed only after this session successfully observed work.
    current_origin = _origin(session.page.url)
    previous = getattr(session, "last_good_urls", {}).get(current_origin)
    if not previous and _origin(session.last_good_url) == current_origin:
        previous = session.last_good_url
    if previous:
        for frame in session.page.frames:
            if await frame.locator('input[type="password"]:visible').count():
                message = await login(session)
                await consent(session)
                if bus:
                    bus.emit("relogin", agent, {"reason": "session expired"})
                try:
                    await session.page.goto(previous, wait_until="domcontentloaded")
                except Exception:
                    pass
                session.notices.append("Session renewal attempted: " + message)
                break
    else:
        # The model initiates first login; it sees consent walls in the DOM.
        return

"""Load scout environment safely, then run the package with its own interpreter."""

from __future__ import annotations

import argparse
import os
import re
import shlex
import shutil
import subprocess
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
PACKAGE = ROOT / "my-agent"
ALLOWED = {
    "CHALLENGE_API_URL", "CHALLENGE_RUN_TOKEN", "CHALLENGE_SCOUTING", "CDP_URL", "CDP_URLS",
    "HEADLESS", "QWEN_BASE_URL", "QWEN_API_KEY", "CLEF_BASE_URL", "CLEF_API_KEY",
}


def _parse_assignments(output: str) -> dict[str, str]:
    values: dict[str, str] = {}
    for line in output.splitlines():
        candidate = line.strip()
        if candidate.startswith("export "):
            candidate = candidate[7:].strip()
        if candidate.startswith("$env:"):
            match = re.fullmatch(r"\$env:([A-Za-z_][A-Za-z0-9_]*)\s*=\s*(.*)", candidate)
            if not match:
                continue
            key, raw = match.groups()
            if len(raw) >= 2 and raw[0] == raw[-1] and raw[0] in "'\"":
                value = raw[1:-1]
            else:
                value = raw
        else:
            match = re.fullmatch(r"([A-Za-z_][A-Za-z0-9_]*)=(.*)", candidate)
            if not match:
                continue
            key, raw = match.groups()
            try:
                parts = shlex.split(raw, posix=True)
                value = parts[0] if len(parts) == 1 else ""
            except ValueError:
                continue
        if key in ALLOWED:
            values[key] = value
    return values


def _cli_path() -> str | None:
    override = os.environ.get("ATIRA_CLI")
    if override:
        return override
    found = shutil.which("atira")
    if found:
        return found
    if os.name == "nt":
        standard = Path(os.environ.get("LOCALAPPDATA", "")) / "atira" / "bin" / "atira.cmd"
        if standard.is_file():
            return str(standard)
    return None


def _scout_env() -> dict[str, str]:
    cli = _cli_path()
    if not cli:
        raise RuntimeError("Atira CLI was not found; set ATIRA_CLI or provide CHALLENGE_SCOUTING")
    command = [cli, "scout", "--challenge", "rfq", "--env"]
    result = subprocess.run(command, cwd=ROOT, capture_output=True, text=True, encoding="utf-8", check=False, timeout=60)
    if result.returncode:
        raise RuntimeError(f"Atira scout command failed (exit {result.returncode})")
    parsed = _parse_assignments(result.stdout)
    if not parsed:
        raise RuntimeError("Atira scout output contained no recognized environment assignments")
    return parsed


def main(argv: list[str] | None = None) -> int:
    parser = argparse.ArgumentParser()
    parser.add_argument("--dry", action="store_true")
    parser.add_argument("--orient", action="store_true")
    parser.add_argument("--budget-s", type=int)
    args = parser.parse_args(argv)
    child_env = os.environ.copy()
    if not (child_env.get("CHALLENGE_SCOUTING") or child_env.get("CHALLENGE_RUN_TOKEN")):
        try:
            child_env.update(_scout_env())
        except RuntimeError as exc:
            print(str(exc), file=sys.stderr)
            return 1
    if args.budget_s is not None:
        child_env["RUN_BUDGET_S"] = str(args.budget_s)
    uv = shutil.which("uv")
    command = ([uv] if uv else [sys.executable, "-m", "uv"]) + ["run", "--no-sync", "python", "-m", "rfq"]
    if args.orient:
        command.append("--orient")
    elif args.dry:
        command.append("--dry")
    return subprocess.run(command, cwd=PACKAGE, env=child_env, check=False).returncode


if __name__ == "__main__":
    raise SystemExit(main())

"""Small read/answer client for the current platform run contract."""

from __future__ import annotations

import json
import time
from datetime import datetime, timezone
from email.utils import parsedate_to_datetime
from urllib.error import HTTPError, URLError
from urllib.request import Request, urlopen

from .config import Settings

USER_AGENT = "atira-rfq-agent/1"


def _request(url: str, token: str | None = None, answer: dict | None = None) -> tuple[int, str]:
    headers = {"Accept": "application/json", "User-Agent": USER_AGENT}
    body = None
    if token:
        headers["x-api-key"] = token
    if answer is not None:
        body = json.dumps(answer, ensure_ascii=False).encode("utf-8")
        headers["Content-Type"] = "application/json"
    request = Request(url, data=body, headers=headers)
    try:
        with urlopen(request, timeout=60 if answer is not None else 30) as response:
            return response.status, response.read().decode("utf-8", errors="replace")
    except HTTPError as exc:
        return exc.code, exc.read().decode("utf-8", errors="replace")


def load_run(settings: Settings) -> dict:
    if settings.run_token:
        if not settings.api_url:
            raise RuntimeError("CHALLENGE_API_URL is required with a run token")
        url = settings.api_url.rstrip("/") + "/v1/runs/current"
        status, body = 0, ""
        for attempt in range(5):
            try:
                status, body = _request(url, settings.run_token)
            except (URLError, OSError):
                status = 0
            if status == 200:
                try:
                    run = json.loads(body)
                except ValueError as exc:
                    raise RuntimeError("Platform returned invalid run JSON") from exc
                if isinstance(run, dict):
                    return run
                raise RuntimeError("Platform run response must be an object")
            if status in (401, 403, 404):
                break
            if attempt < 4:
                time.sleep(2 * (attempt + 1))
        raise RuntimeError(f"Could not load current run (HTTP {status})")
    if settings.scouting is not None:
        return settings.scouting
    raise RuntimeError("No run is configured; set CHALLENGE_RUN_TOKEN or CHALLENGE_SCOUTING")


def seconds_left(run: dict, now: float | None = None) -> float:
    expiry = run.get("expires_at")
    if expiry is None:
        return float("inf")
    if isinstance(expiry, str):
        try:
            parsed = datetime.fromisoformat(expiry.replace("Z", "+00:00"))
        except ValueError:
            try:
                parsed = parsedate_to_datetime(expiry)
            except (TypeError, ValueError):
                return float("inf")
        timestamp = parsed.replace(tzinfo=timezone.utc).timestamp() if parsed.tzinfo is None else parsed.timestamp()
    else:
        timestamp = float(expiry)
        if timestamp > 10_000_000_000:
            timestamp /= 1000
    return timestamp - (time.time() if now is None else now)


def submit_api_answer(run: dict, token: str, answer: dict) -> tuple[int, str]:
    submission = run.get("submission") or {}
    if submission.get("kind") != "api":
        raise ValueError("This run does not accept API submission")
    url = run.get("answer_url") or submission.get("url")
    if not url:
        raise ValueError("API submission target is missing")
    return _request(url, token, answer)

