        if target is None:
            label = (seen.get(int(element_id)) or {}).get("label", "")
            raise LookupError(f"control [{element_id}] '{label[:60]}' is no longer present as observed")
        return target
    rebound = dict(action)
    for key in ("id", "submit_id"):
        if rebound.get(key) is not None:
