// Dev-only: do fresh connections from this machine intermittently stall? Time many independent cookieless
// requests per host (new connection each time) and report the distribution and any that hang.
import { readFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import https from "node:https";
import http from "node:http";

const here = dirname(fileURLToPath(import.meta.url));
const perHost = Number(process.argv[2] || 25);
const limitMs = Number(process.argv[3] || 12000);
const scouting = JSON.parse(readFileSync(join(here, "..", "scouting.json"), "utf8"));
const env = JSON.parse(readFileSync(join(here, "..", "scout_env.json"), "utf8"));
const targets = [
  ...scouting.access.map(s => ({ name: s.siteId, url: s.url + "/" })),
  { name: "platform", url: "https://ehl-challenge.atira.ai/v1/challenges/rfq/leaderboard" },
  { name: "local-proxy", url: env.QWEN_BASE_URL.replace(/\/qwen\/v1$/, "/") },
];

function once(url) {
  return new Promise(resolve => {
    const started = Date.now();
    const lib = url.startsWith("https") ? https : http;
    const phases = {};
    // agent:false forces a brand-new connection, which is what a new tab or a new CLI process makes.
    const req = lib.get(url, { agent: false, timeout: limitMs, headers: { "user-agent": "conn-check" } }, res => {
      phases.firstByte = Date.now() - started;
      res.resume();
      res.on("end", () => resolve({ ok: true, ms: Date.now() - started, status: res.statusCode, phases }));
    });
    req.on("socket", socket => {
      socket.on("lookup", () => { phases.dns = Date.now() - started; });
      socket.on("connect", () => { phases.tcp = Date.now() - started; });
      socket.on("secureConnect", () => { phases.tls = Date.now() - started; });
    });
    req.on("timeout", () => { req.destroy(new Error("timeout")); });
    req.on("error", e => resolve({ ok: false, ms: Date.now() - started, error: e.code || e.message, phases }));
  });
}

for (const target of targets) {
  const results = [];
  for (let i = 0; i < perHost; i++) results.push(await once(target.url));
  const good = results.filter(r => r.ok).map(r => r.ms).sort((a, b) => a - b);
  const bad = results.filter(r => !r.ok);
  const slow = results.filter(r => r.ok && r.ms > 3000);
  const q = p => good.length ? good[Math.min(good.length - 1, Math.floor(p * good.length))] : "-";
  console.log(`${target.name.padEnd(16)} n=${results.length} ok=${good.length} median=${q(0.5)}ms p90=${q(0.9)}ms max=${good.at(-1) ?? "-"}ms ` +
              `slow(>3s)=${slow.length} failed=${bad.length}`);
  for (const r of [...bad, ...slow]) {
    console.log(`     ${r.ok ? "slow" : "FAILED " + r.error} after ${r.ms}ms; reached: ${JSON.stringify(r.phases)}`);
  }
}

