first, last, count = {}, {}, Counter()
for e in ev:
    if e["type"] == "record_added":
        k = e["agent"] + "/" + e["data"]["kind"]
        first.setdefault(k, rel(e)); last[k] = rel(e); count[k] += 1
for k in sorted(first): print(f"   {k:24} first {first[k]}  last {last[k]}  count {count[k]}")
print("   never recorded: Material, PriceCondition" if not any("Material" in k or "PriceCondition" in k for k in first) else "")
print("== 3. EVERY 'TAB REPLACED' AND PAGE ERROR ==")
for e in ev:
    if e["type"] == "retry":
        print("  ", rel(e), e["agent"], json.dumps(e["data"], ensure_ascii=False)[:250])
print("== 4. MODEL CALLS THAT GOT NO ANSWER ==")
