for e in mr[:4]: print("  ", rel(e), e["agent"], json.dumps(e["data"], ensure_ascii=False)[:200])
print("== 5. SUBMITTER ==")
for e in ev:
    if e["agent"] == "submitter" and e["type"] in ("agent_step", "retry", "model_retry", "agent_done", "submit_step"):
        d = e["data"]
        if e["type"] == "agent_step":
            a = d["action"] if isinstance(d["action"], list) else [d["action"]]
            print("  ", rel(e), "step", d["step"], "; ".join((x.get("kind","?") + ":" + str(x.get("target") or x.get("url") or ""))[:40] for x in a)[:150], "||", d["thought"][:110])
        else: print("  ", rel(e), e["type"], json.dumps(d, ensure_ascii=False, default=str)[:260])
