for line in open(sys.argv[1], encoding="utf-8", errors="replace"):
    i = line.find("@@EVT ")
    if i >= 0:
        try: ev.append(json.loads(line[i+6:]))
        except ValueError: pass
t0 = datetime.fromisoformat(ev[0]["time"])
rel = lambda e: "%02d:%02d" % divmod(int((datetime.fromisoformat(e["time"]) - t0).total_seconds()), 60)
for e in ev:
    if e["type"] != "record_added": continue
    k, r = e["data"]["kind"], e["data"]["record"]
    if k == "Material":
        print(rel(e), "MATERIAL", {x: r[x] for x in ("number", "status", "katalog_group", "bore", "stroke", "pressure", "mounting", "certification", "stock_qty", "lead_weeks_stock", "lead_weeks_production")})
    elif k == "PriceCondition":
        print(rel(e), "PRICE", json.dumps(r, ensure_ascii=False))
        print("        snippet:", e["data"]["provenance"]["snippet"][:300])
    elif k == "MailRecord":
        print(rel(e), "MAIL", {x: r[x] for x in ("message_id", "sender", "date", "kind", "reference", "payload")})
    elif k == "TenderPosition":
        print(rel(e), "POSITION", r)
