        valid = []
        for row in conditions.get(norm_ref(material.get("material_number")), []):
            start, end = when(row.get("valid_from")), day_end(row.get("valid_to"))
            if (start is None or start <= scenario) and (end is None or scenario <= end):
                valid.append(row)
