        line["setup"] = number(assigned.get("setup_fee_eur")) or Decimal(0)
        key = norm_ref(assigned.get("packaging_key"))
        carton = number(material.get("pieces_per_carton"))
        if not key:
            line["packaging"] = Decimal(0)
        elif tariffs.get(key) is None or not carton:
            line["gaps"].append(f"packaging tariff {assigned.get('packaging_key')} or carton size")
        else:
            line["packaging"] = Decimal(math.ceil(quantity / carton)) * tariffs[key]
        pooled = demand[norm_ref(line["material_number"])]
        commitment = commitments.get(norm_ref(assigned.get("delivery_key")))
        if assigned.get("delivery_key") and not commitment:
            line["gaps"].append(f"delivery commitment {assigned.get('delivery_key')}")
        stock = number(material.get("available_stock"))
        if (commitment and norm_ref(commitment.get("material_number")) == norm_ref(line["material_number"])
                and number(commitment.get("max_quantity")) is not None
                and pooled <= number(commitment.get("max_quantity"))
                and number(commitment.get("lead_time_weeks")) is not None):
            line["lead_time_weeks"] = int(number(commitment["lead_time_weeks"]))
        elif stock is not None and pooled <= stock and number(material.get("stock_lead_weeks")) is not None:
            line["lead_time_weeks"] = int(number(material["stock_lead_weeks"]))
        elif stock is not None and number(material.get("production_lead_weeks")) is not None:
