:root {
  --bg: #ffffff;
  --panel: #ffffff;
  --soft: #f4f4f5;
  --softer: #fafafa;
  --line: #e4e4e7;
  --text: #09090b;
  --muted: #71717a;
  --faint: #a1a1aa;
  --ring: #18181b;
  --good: #16a34a;
  --good-soft: #dcfce7;
  --warn: #d97706;
  --warn-soft: #fef3c7;
  --bad: #dc2626;
  --bad-soft: #fee2e2;
  --info: #2563eb;
  --info-soft: #dbeafe;
  --a: #2563eb;
  --b: #16a34a;
  --c: #d97706;
  --d: #7c3aed;
  --e: #71717a;
  --gather: #60a5fa;
  --decide: #c084fc;
  --submit: #fb923c;
  --qwen: #3b82f6;
  --clef: #f59e0b;
  --radius: 10px;
  --shadow: 0 1px 2px rgba(0, 0, 0, 0.04);
}

:root[data-theme="dark"] {
  --bg: #09090b;
  --panel: #0c0c0f;
  --soft: #18181b;
  --softer: #111113;
  --line: #27272a;
  --text: #fafafa;
  --muted: #a1a1aa;
  --faint: #71717a;
  --ring: #fafafa;
  --good: #4ade80;
  --good-soft: #052e16;
  --warn: #fbbf24;
  --warn-soft: #3a2506;
  --bad: #f87171;
  --bad-soft: #3f1212;
  --info: #60a5fa;
  --info-soft: #0f2547;
  --a: #60a5fa;
  --b: #4ade80;
  --c: #fbbf24;
  --d: #a78bfa;
  --e: #a1a1aa;
  --shadow: none;
}

@media (prefers-color-scheme: dark) {
  :root:not([data-theme="light"]) {
    --bg: #09090b;
    --panel: #0c0c0f;
    --soft: #18181b;
    --softer: #111113;
    --line: #27272a;
    --text: #fafafa;
    --muted: #a1a1aa;
