        h("span", { class: "n", text: index + 1 }), h("h3", { text: finding.title }), h("span", { class: "figure", text: finding.figure }),
        h("p", { text: finding.body }), finding.runs.length ? h("div", { class: "chips" }, finding.runs.map(chip)) : null))),
      h("div", { class: "grid cols-2" },
        card("Where points were lost", `${lost.total} runs with an answer`, table([
          { label: "Field", cell: (row) => FIELD[row.kind] || row.kind.replace(/_/g, " ") },
          { label: "Runs", right: true, cell: (row) => `${row.runs} of ${lost.total}` },
          { label: "Points", right: true, cell: (row) => row.points.toFixed(1) },
          { label: "", cell: (row) => h("div", { class: "meter" }, h("span", { style: `width:${(100 * row.points) / most}%` })) },
        ], lost.rows), true),
        h("div", { class: "stack" },
          card("Outcome of every run", null, table([
            { label: "Outcome", cell: (row) => row.label },
            { label: "Runs", right: true, cell: (row) => row.count },
            { label: "Cost", right: true, cell: (row) => money(row.cost, 2) },
            { label: "Run time", right: true, cell: (row) => Math.round(row.seconds / 60) + " min" },
          ], outcomes()), true),
          card("By code line", "told apart by package contents and log style", table([
            { label: "Line", cell: (row) => h("span", { tip: row.name }, h("span", { class: "dot line-" + row.line, style: "margin-right:6px" }), row.line) },
            { label: "What it is", cls: "note", cell: (row) => row.name },
            { label: "Runs", right: true, cell: (row) => row.count },
            { label: "Answers", right: true, cell: (row) => row.answers },
            { label: "35+", right: true, cell: (row) => row.high },
            { label: "Best", right: true, cell: (row) => row.best },
            { label: "Median cost", right: true, cell: (row) => money(row.cost) },
            { label: "Median time", right: true, cell: (row) => clock(row.seconds) },
          ], lines()), true))),
