        { label: "Worker", cell: (row) => [h("div", { text: row.name }), row.stop ? h("div", { class: "small muted", text: row.stop }) : null] },
        { label: "Active", cls: "nowrap", cell: (row) => `${clock(row.first)}–${clock(row.last)}` },
        { label: "Actions", right: true, cell: (row) => row.steps },
        { label: "Failed", right: true, cell: (row) => row.errors + row.refused || "" },
        { label: "Calls", right: true, cell: (row) => row.modelCalls },
        { label: "Cost", right: true, cell: (row) => (row.cost ? money(row.cost) : "–") },
        { label: "In calls", right: true, cell: (row) => (row.inCalls ? whole(row.inCalls) + " s" : "–") },
        { label: "Tools", cls: "small", cell: (row) => row.tools.slice(0, 5).map(([tool, count]) => `${tool} ${count}`).join(" · ") },
        { label: "Sat still", cls: "small note", cell: (row) => h("ul", { class: "sub-list" },
          row.quiet.slice(0, 3).map(([from, seconds]) => h("li", {}, h("b", { text: span(seconds) }), ` quiet from ${clock(from)}`)),
          row.stays.slice(0, 3).map(([page, from, seconds, actions]) => h("li", { tip: page }, h("b", { text: span(seconds) }), ` on one page from ${clock(from)}, ${actions} actions`)),
          row.repeats.slice(0, 3).map(([what, from, seconds, count, bad]) => h("li", { tip: what }, h("b", { text: `${count}×` }), ` ${what.split(" ")[0]} in a row from ${clock(from)} (${span(seconds)}${bad ? ", " + bad + " failed" : ""})`))) },
      ], run.workers), true),
      h("div", { class: "grid cols-2" },
        card("Failures in this run", null, table([
          { label: "Times", right: true, cell: (row) => row[3] },
          { label: "Worker", cls: "nowrap", cell: (row) => row[0] || "–" },
          { label: "Tool", cls: "mono nowrap", cell: (row) => row[1] || "–" },
          { label: "Answer", cls: "wraptext", cell: (row) => [row[2], row[6] ? h("div", { class: "mono faint", text: row[6] }) : null] },
          { label: "First–last", cls: "nowrap", cell: (row) => `${clock(row[4])}–${clock(row[5])}` },
        ], run.errors), true),
        h("div", { class: "stack" },
          card("Waits", null, h("dl", { class: "kv" },
            h("dt", { text: "No call in flight" }), h("dd", { text: run.idle.length ? run.idle.slice(0, 6).map(([from, seconds]) => `${span(seconds)} from ${clock(from)}`).join(" · ") : "never for 15 s or more" }),
            h("dt", { text: "Slowest calls" }), h("dd", { text: run.slow.length ? run.slow.slice(0, 6).map(([start, took, out]) => `${Math.round(took)} s at ${clock(start)} (${whole(out)} tokens out)`).join(" · ") : "none of 30 s or more" }),
            h("dt", { text: "Calls re-sent" }), h("dd", { text: run.retries.length ? run.retries.map(([kind, count]) => `${kind} ${count}`).join(" · ") : "none logged" }),
            h("dt", { text: "Browser silences" }), h("dd", { text: Object.entries(run.browsers).map(([number, browser]) => `b${number}${browser.owner ? " (" + browser.owner + ")" : ""}: ${browser.quiet.length ? span(browser.quiet[0][1]) + " from " + clock(browser.quiet[0][0]) : "none"}`).join(" · ") || "no inputs recorded" }))),
          submission ? card("Submitter", null, [h("dl", { class: "kv" },
            h("dt", { text: "First seen" }), h("dd", { text: clock(submission.firstPrepared) }),
            h("dt", { text: "After the bid" }), h("dd", { text: `${submission.steps} actions, ${submission.errors} failed, ${submission.modelCalls} model answers` }),
            h("dt", { text: "Answer entered" }), h("dd", { text: submission.confirmed ? "yes" : "no" })),
            h("h4", { text: "Last lines", style: "margin:14px 0 6px" }),
            h("ul", { class: "sub-list" }, submission.last.map(([at, kind, action, text]) => h("li", {}, h("b", { text: clock(at) }), ` ${action || kind}: ${text}`)))]) : null)),
      card("Points per field", run.score ? `${run.score.lost.length} fields lost points` : null, scoreGrid(run)),
      card("Log", "what the agent logged, reduced to one shape across the code lines", logTable(run), true),
      run.diagnosis.length ? card("Platform diagnosis", null, h("ul", { class: "bullets" }, run.diagnosis.map((line) => h("li", { text: line })))) : null);
  }

  // ---------------------------------------------------------------- shell

  function render(keepScroll) {
    const at = window.scrollY;
    for (const tab of document.querySelectorAll(".tab")) tab.setAttribute("aria-selected", tab.dataset.tab === state.tab ? "true" : "false");
    view.replaceChildren({ overview, runs: runsTab, stuck: stuckTab, run: runTab }[state.tab]());
    if (keepScroll) window.scrollTo({ top: at });
  }

  function route() {
    const [tab, id] = location.hash.replace(/^#/, "").split("/");
    if (["overview", "runs", "stuck", "run"].includes(tab)) state.tab = tab;
    if (tab === "run" && byId[id]) state.run = id;
    render();
  }

  document.getElementById("tabs").addEventListener("click", (event) => {
    const tab = event.target.closest(".tab");
    if (!tab) return;
    location.hash = tab.dataset.tab === "run" ? "run/" + state.run : tab.dataset.tab;
  });
  window.addEventListener("hashchange", route);

  document.addEventListener("mousemove", (event) => {
    const target = event.target.closest && event.target.closest("[data-tip]");
    if (!target || !target.dataset.tip) { tip.hidden = true; return; }
    tip.textContent = target.dataset.tip;
    tip.hidden = false;
    const box = tip.getBoundingClientRect();
    tip.style.left = Math.max(8, Math.min(window.innerWidth - box.width - 8, event.clientX + 14)) + "px";
    tip.style.top = (event.clientY + box.height + 24 > window.innerHeight ? event.clientY - box.height - 12 : event.clientY + 16) + "px";
  });

  const themeButton = document.getElementById("theme");
  function setTheme(name) {
    document.documentElement.dataset.theme = name;
    themeButton.textContent = name === "dark" ? "Light" : "Dark";
    try { localStorage.setItem("run-report-theme", name); } catch (error) { /* storage can be blocked for local files */ }
  }
  let saved = null;
  try { saved = localStorage.getItem("run-report-theme"); } catch (error) { saved = null; }
  setTheme(saved || (window.matchMedia("(prefers-color-scheme: dark)").matches ? "dark" : "light"));
  themeButton.addEventListener("click", () => setTheme(document.documentElement.dataset.theme === "dark" ? "light" : "dark"));

  document.getElementById("subtitle").textContent = `${runs.length} runs · ${R.overview.asOf} · rfq challenge`;
  document.getElementById("foot").textContent = "Built from the platform's read-only run records. Values seen on the practice sites appear in the log lines; keep this folder outside the repository.";
  route();
})();

