20	    'SECTION','SUMMARY','TABLE','TBODY','THEAD','TFOOT','TR','UL','CAPTION','LEGEND']);
21	  const SKIP = new Set(['SCRIPT','STYLE','NOSCRIPT','TEMPLATE','HEAD','META','LINK','SVG']);
22	  const ROLES = new Set(['button','link','tab','menuitem','checkbox','radio','option','switch','combobox','textbox',
23	    'slider','spinbutton','treeitem','searchbox','menuitemcheckbox','menuitemradio']);
24	  const ZW = /[​-‏⁠﻿­]/g;
25	  let id = start, cur = '', row = 0, password = false;
26	  const lines = [], controls = [];
