28	  const flush = () => { if (row) { cur += ' '; return; } const t = cur.replace(/[ \t]+/g, ' ').trim(); if (t) lines.push(t); cur = ''; };
29	  const visible = (el, st) => {
30	    if (st.display === 'none' || st.visibility === 'hidden' || st.visibility === 'collapse') return false;
