80	      if (el.placeholder && c.label !== clean(el.placeholder)) c.extra += ` placeholder "${clean(el.placeholder).slice(0, 40)}"`;
81	    }
82	    if (tag === 'TEXTAREA') { c.value = el.value || ''; if (el.value) c.extra += ` = "${clean(el.value).slice(0, 60)}"`; }
83	    if (tag === 'SELECT') {
84	      c.options = Array.from(el.options).map(o => clean(o.text));
85	      c.value = el.selectedIndex >= 0 ? clean(el.options[el.selectedIndex].text) : '';
86	      const shown = Array.from(el.options).map(o => (o.selected ? '*' : '') + clean(o.text).slice(0, 40));
87	      c.extra += ' options: ' + shown.slice(0, 40).join(' | ') + (shown.length > 40 ? ` | …(${shown.length})` : '');
