98	    }
99	    if (el.title && clean(el.title) !== c.label) c.extra += ` (title: ${clean(el.title).slice(0, 80)})`;
100	    if (tag === 'SUMMARY') c.extra += el.parentElement && el.parentElement.open ? ' (open)' : ' (closed)';
101	    if (tag === 'A') {
102	      const href = el.getAttribute('href') || '';
103	      if (href && href !== '#' && !href.startsWith('javascript')) c.href = el.href;
104	      if (c.href) c.extra += ' →' + c.href.replace(location.origin, '').slice(0, 90);
