170	@dataclass
171	class Control:
172	    id: int
173	    kind: str
174	    label: str
175	    frame: int
176	    href: str = ""
177	    extra: str = ""
178	    value: str | None = None
179	    options: list[str] | None = None
180	    checked: bool | None = None
181	    disabled: bool = False
182	    readonly: bool = False
183	    context: str = ""  # the text line the control sits in, for choosing among look-alike controls
184	
185	    @property
186	    def fillable(self) -> bool:
187	        return not self.disabled and not self.readonly and self.kind in (
188	            "input", "search", "email", "number", "tel", "password", "textarea", "textbox", "searchbox", "select",
189	            "range", "checkbox", "radio", "date", "datetime-local", "combobox", "slider", "switch")
190	
191	    def describe(self) -> str:
192	        text = f"{self.kind} '{self.label}'{self.extra}"
193	        return text + (f" (row: {self.context})" if self.context else "")
194	
195	
196	@dataclass
197	class Observation:
198	    url: str
199	    title: str
200	    text: str
201	    controls: dict[int, Control] = field(default_factory=dict)
202	    password: bool = False
203	
204	    @property
205	    def signature(self) -> str:
206	        body = re.sub(r"\[\d+:", "[", self.text)
207	        return hashlib.sha1((self.url.split("#")[0] + body).encode()).hexdigest()[:16]
208	
209	    def clip(self, limit: int) -> str:
210	        head = f"URL: {self.url}\nTitle: {self.title}\n"
211	        return head + (self.text if len(self.text) <= limit else self.text[:limit] + "\n[… page text truncated]")
212	
213	
214	def text_of_document(name: str, data: bytes, limit: int = 20000) -> str:
215	    """Text of a downloaded document the model chose: ZIP members, text formats and (if available) PDFs."""
216	    lower = name.lower()
217	    if lower.endswith(".zip") or data[:2] == b"PK":
218	        parts = []
219	        with zipfile.ZipFile(io.BytesIO(data)) as archive:
220	            for member in archive.namelist():
221	                if not member.endswith("/"):
222	                    parts.append(f"--- {member}\n" + text_of_document(member, archive.read(member), limit // 2))
223	        return "\n".join(parts)[:limit]
224	    if lower.endswith(".pdf") or data[:4] == b"%PDF":
225	        try:
226	            from pypdf import PdfReader  # optional; present only if installed
227	            return "\n".join(page.extract_text() or "" for page in PdfReader(io.BytesIO(data)).pages)[:limit]
228	        except Exception as error:
229	            return f"[PDF {name}: no text extracted ({type(error).__name__}); open it in the browser instead]"
230	    for encoding in ("utf-8", "cp1252", "latin-1"):
231	        try:
232	            text = data.decode(encoding)
233	            break
234	        except UnicodeDecodeError:
235	            continue
236	    if lower.endswith((".html", ".htm")) or "<html" in text[:500].lower():
237	        text = re.sub(r"<(script|style)[^>]*>.*?</\1>", " ", text, flags=re.S | re.I)
238	        text = re.sub(r"<br\s*/?>|</(p|div|tr|li|h\d)>", "\n", text, flags=re.I)
239	        text = re.sub(r"<[^>]+>", " ", text)
240	    return re.sub(r"[ \t]+", " ", text)[:limit]
