243	class Tab:
244	    """One website's browser context: the page a worker drives plus helpers for model-chosen actions."""
245	
246	    def __init__(self, site: dict, context, page, log=print):
247	        self.site = site
248	        self.context = context
249	        self.page = page
250	        self.log = log
251	        self.obs: Observation | None = None
252	        self.events: list[str] = []  # dialogs, downloads and popups since the last observation
253	        self.host = urlparse(site["url"]).netloc
254	        if page is not None:  # None: the tab's page is opened later with open()
255	            self._watch(page)
256	
257	    # ---------------------------------------------------------------- events
258	    def _watch(self, page):
259	        page.on("dialog", self._on_dialog)
260	        page.on("download", lambda download: asyncio.ensure_future(self._on_download(download)))
261	        page.on("popup", self._on_popup)
262	
263	    async def _on_dialog(self, dialog):
264	        self.events.append(f"browser {dialog.type} dialog '{dialog.message[:200]}' was accepted")
265	        try:
266	            await dialog.accept()
267	        except Exception:
268	            pass
269	
270	    async def _on_download(self, download):
271	        try:
272	            path = await download.path()
273	            data = open(path, "rb").read() if path else b""
274	            self.events.append(f"downloaded {download.suggested_filename}:\n" + text_of_document(download.suggested_filename, data))
275	        except Exception as error:
276	            self.events.append(f"download {download.suggested_filename} failed: {error}")
277	
278	    def _on_popup(self, popup):
279	        self.events.append("a new window opened and is now the active page")
280	        self._watch(popup)
281	        self.page = popup
282	
283	    async def open(self, url: str) -> str:
284	        """Open this tab's own page in its context (sharing the session) and load `url` there."""
285	        self.page = await self.context.new_page()
286	        self._watch(self.page)
287	        await self.page.set_viewport_size({"width": 1280, "height": 800})
288	        return await self.goto(url if url.startswith("http") else self.site["url"])
289	
290	    # ------------------------------------------------------------ observing
291	    async def observe(self) -> Observation:
292	        if self.page.is_closed():
293	            open_pages = [p for p in self.context.pages if not p.is_closed()]
294	            self.page = open_pages[-1] if open_pages else await self.context.new_page()
295	        obs = await self._render(self.page)
296	        if self.events:
297	            obs.text = "\n".join(f"[event: {e[:3000]}]" for e in self.events) + "\n" + obs.text
298	            self.events.clear()
299	        self.obs = obs
300	        return obs
301	
302	    async def _render(self, page) -> Observation:
303	        parts, controls, password, next_id, title = [], {}, False, 1, ""
304	        for index, frame in enumerate(page.frames):
305	            if frame.is_detached() or (index and frame.url in ("", "about:blank")):
306	                continue
307	            try:
308	                result = await asyncio.wait_for(frame.evaluate(OBSERVE_JS, next_id), 8)
309	            except Exception:
310	                continue
311	            next_id = result["next"]
312	            password = password or result["password"]
313	            if index == 0:
314	                title = result["title"]
315	                parts.append(result["text"])
316	            elif result["text"].strip():
317	                parts.append(f"--- frame {frame.url.replace('https://' + self.host, '')}\n{result['text']}")
318	            for item in result["controls"]:
319	                controls[item["id"]] = Control(
320	                    id=item["id"], kind=item["kind"], label=item["label"], frame=index, href=item.get("href", ""),
321	                    extra=item.get("extra", ""), value=item.get("value"), options=item.get("options"),
322	                    checked=item.get("checked"), disabled=bool(item.get("disabled")), readonly=bool(item.get("readonly")))
323	        text = "\n".join(parts)
324	        for line in text.splitlines():
325	            ids = [int(m) for m in re.findall(r"\[(\d+):", line)]
326	            context = re.sub(r"\s+", " ", re.sub(r"\[\d+:[^\]]*\]", " ", line)).strip()[:90]
327	            for cid in ids:
328	                if cid in controls:
329	                    controls[cid].context = context
330	        return Observation(url=page.url, title=title, text=text, controls=controls, password=password)
331	
332	    def _locate(self, cid: int):
333	        control = self.obs.controls.get(cid) if self.obs else None
334	        if control is None:
335	            raise ValueError(f"control {cid} is not on the current page; observe again")
336	        frames = self.page.frames
337	        frame = frames[control.frame] if control.frame < len(frames) else self.page.main_frame
338	        return control, frame.locator(f'[data-aid="{cid}"]').first
339	
340	    # -------------------------------------------------------------- actions
341	    async def settle(self, before: str | None = None):
342	        """Wait briefly for the navigation or DOM update an action started."""
343	        await asyncio.sleep(0.25)
344	        for _ in range(2):
345	            try:
346	                await self.page.wait_for_load_state("domcontentloaded", timeout=6000)
347	            except Exception:
348	                pass
349	            for frame in self.page.frames[1:]:
350	                try:
351	                    await frame.wait_for_load_state("domcontentloaded", timeout=3000)
352	                except Exception:
353	                    pass
354	            if before is None or self.page.url != before:
355	                break
356	            await asyncio.sleep(0.2)
357	        await self._retry_error_page()
358	
359	    async def _retry_error_page(self):
360	        """Flaky server errors: reload a page whose main document came back with a 5xx status, at most twice."""
361	        for _ in range(2):
362	            try:
363	                status = await asyncio.wait_for(self.page.evaluate(
364	                    "() => (performance.getEntriesByType('navigation')[0] || {}).responseStatus || 0"), 3)
365	            except Exception:
366	                return
367	            if not status or status < 500:
368	                return
369	            self.log(f"[{self.site['siteId']}] server error {status}; reloading")
370	            await asyncio.sleep(0.4)
371	            try:
372	                await self.page.reload(wait_until="domcontentloaded", timeout=10000)
373	            except Exception:
374	                return
375	
376	    async def click(self, cid: int) -> str:
377	        control, locator = self._locate(cid)
378	        if control.disabled and control.href:  # a locked overlay disables the link, not its target
379	            await self.goto(control.href)
380	            return f"opened the target of {control.describe()[:120]}"
381	        before = self.page.url
382	        try:
383	            await locator.evaluate(OPEN_DETAILS_JS, timeout=3000)
384	            await locator.click(timeout=3000)
385	        except Exception:
386	            try:
387	                await locator.evaluate("e => e.click()", timeout=3000)
388	            except Exception:
389	                if not control.href:
390	                    raise
391	                await self.goto(control.href)
392	        await self.settle(before)
393	        return f"clicked {control.describe()[:120]}"
394	
395	    async def fill(self, cid: int, value: str) -> str:
396	        control, locator = self._locate(cid)
397	        value = str(value)
398	        if control.kind in ("range", "slider"):
399	            await locator.evaluate("""(e, v) => { const set = Object.getOwnPropertyDescriptor(HTMLInputElement.prototype, 'value').set;
400	                set.call(e, v); e.dispatchEvent(new Event('input', {bubbles: true})); e.dispatchEvent(new Event('change', {bubbles: true})); }""", value, timeout=3000)
401	            return f"set {control.label} to {value}"
402	        if control.kind == "select":
403	            return await self.select(cid, value)
404	        await locator.evaluate(OPEN_DETAILS_JS, timeout=3000)
405	        await locator.fill(value, timeout=4000)
406	        return f"filled {control.label!r} with {value!r}"
407	
408	    async def select(self, cid: int, option: str) -> str:
409	        control, locator = self._locate(cid)
410	        options = control.options or []
411	        chosen = match_option(option, options)
412	        if chosen is None:
413	            raise ValueError(f"no option matches {option!r}; options are {options[:40]}")
414	        before = self.page.url
415	        await locator.select_option(label=chosen, timeout=4000)
416	        await self.settle(before)
417	        return f"selected {chosen!r} in {control.label!r}"
418	
419	    async def check(self, cid: int, on: bool = True) -> str:
420	        control, locator = self._locate(cid)
421	        try:
422	            await locator.set_checked(on, timeout=3000)
423	        except Exception:
424	            if bool(control.checked) != on:
425	                await locator.evaluate("e => e.click()", timeout=3000)
426	        return f"{'checked' if on else 'unchecked'} {control.label!r}"
427	
428	    async def press(self, key: str, cid: int | None = None) -> str:
429	        before = self.page.url
430	        if cid is not None:
431	            await self._locate(cid)[1].press(key, timeout=3000)
432	        else:
433	            await asyncio.wait_for(self.page.keyboard.press(key), 5)
434	        await self.settle(before)
435	        return f"pressed {key}"
436	
437	    def resolve(self, url: str) -> str:
438	        target = urljoin(self.page.url if self.page.url.startswith("http") else self.site["url"], url or "/")
439	        if urlparse(target).netloc != self.host:
440	            raise ValueError(f"{target} is not on this website")
441	        return target
442	
443	    async def goto(self, url: str) -> str:
444	        target = self.resolve(url)
445	        await self.page.goto(target, wait_until="domcontentloaded", timeout=15000)
446	        await self.settle()
447	        return f"opened {target}"
448	
449	    async def back(self) -> str:
450	        await self.page.go_back(wait_until="domcontentloaded", timeout=10000)
451	        await self.settle()
452	        return "went back"
453	
454	    async def screenshot(self) -> str:
455	        import base64
456	        data = await self.page.screenshot(type="jpeg", quality=70, timeout=8000)
457	        return "data:image/jpeg;base64," + base64.b64encode(data).decode()
458	
459	    # -------------------------------------------------------------- helpers
460	    async def login(self) -> str:
461	        """Fill the run's credentials into the visible login form and submit it (the model chose to sign in)."""
462	        credentials = self.site["credentials"]
463	        for frame in self.page.frames:
464	            password = frame.locator("input[type=password]:visible").first
465	            if not await password.count():
466	                continue
467	            user = frame.locator("form:has(input[type=password]) input:visible:not([type=password]):not([type=hidden])"
468	                                 ":not([type=checkbox]):not([type=radio]):not([readonly]):not([disabled])").first
469	            if not await user.count():
470	                user = frame.locator("input:visible:not([type=password]):not([type=hidden]):not([type=checkbox])"
471	                                     ":not([readonly]):not([disabled])").first
472	            before = self.page.url
473	            await user.fill(credentials["username"], timeout=3000)
474	            await password.fill(credentials["password"], timeout=3000)
475	            await password.press("Enter", timeout=3000)
476	            await self.settle(before)
477	            return "signed in with the run credentials"
478	        raise ValueError("no login form on this page")
479	
480	    async def read_pages(self, urls: list[str], limit: int = 12000) -> list[tuple[str, str]]:
481	        """Open model-selected pages of this website in parallel tabs (same session) and return their text."""
482	        async def read(url: str) -> tuple[str, str]:
483	            page = await self.context.new_page()
484	            try:
485	                target = self.resolve(url)
486	                for attempt in range(3):
487	                    response = await page.goto(target, wait_until="domcontentloaded", timeout=15000)
488	                    await asyncio.sleep(0.35)
489	                    if not response or response.status < 500:
490	                        break
491	                    await asyncio.sleep(0.5)
492	                obs = await asyncio.wait_for(self._render(page), 20)
493	                if obs.password:
494	                    return url, "[session expired: this page shows a login form; sign in on the main page, then read again]"
495	                return url, obs.clip(limit)
496	            except Exception as error:
497	                return url, f"[could not read: {type(error).__name__}: {str(error)[:200]}]"
498	            finally:
499	                await page.close()
500	        semaphore = asyncio.Semaphore(8)
501	
502	        async def bounded(url):
503	            async with semaphore:
504	                return await read(url)
505	        return await asyncio.gather(*(bounded(url) for url in urls[:24]))
506	
507	    async def paginate(self, cid: int, max_pages: int = 8, limit: int = 30000) -> str:
508	        """Follow the model-chosen 'next page' / 'load more' control through a result set; new lines of each page."""
509	        control = self.obs.controls.get(cid) if self.obs else None
510	        if control is None:
511	            raise ValueError(f"control {cid} is not on the current page")
512	        key = (control.kind, control.label)
513	        seen = set(self.obs.text.splitlines())
514	        pages, total = [], 0
515	        for _ in range(max_pages):
516	            await self.click(cid)
517	            obs = await self.observe()
518	            fresh = [line for line in obs.text.splitlines() if line not in seen]
519	            seen.update(fresh)
520	            pages.append("\n".join(fresh))
521	            total += len(pages[-1])
522	            nxt = [c for c in obs.controls.values() if (c.kind, c.label) == key and not c.disabled]
523	            if not nxt or total > limit or not fresh:
524	                break
525	            cid = nxt[0].id
526	        return "\n--- next page ---\n".join(pages)[:limit]
527	
528	
529	def normalize(text: str) -> str:
530	    return re.sub(r"\s+", " ", re.sub(r"[​-‏⁠﻿]", "", str(text))).strip().casefold()
531	
532	
533	def match_option(wanted, options: list[str]) -> str | None:
534	    """The option a model's value refers to: exact text, a number equal to the value, or a unique containment."""
535	    want = normalize(wanted)
536	    if not want:
537	        return None
538	    for option in options:
539	        if normalize(option) == want:
540	            return option
541	    number = re.fullmatch(r"-?\d+(?:[.,]\d+)?", want)
542	    if number:
543	        for option in options:
544	            first = re.match(r"\s*(-?\d+(?:[.,]\d+)?)", normalize(option))
545	            if first and first.group(1).replace(",", ".") == want.replace(",", "."):
546	                return option
547	    containing = [o for o in options if want in normalize(o) or (normalize(o) and normalize(o) in want and len(normalize(o)) > 2)]
548	    return containing[0] if len(containing) == 1 else None
549	
550	
551	def now() -> float:
552	    return time.monotonic()
