        brief.append('## '+str(label)+'  SHIP FIRST: '+str(r.get('ship_first'))[:420])
        for v in r['verdicts']: brief.append('  - ['+v.get('verdict','?')+'] '+v.get('title','')[:150])
        if r.get('missed'): brief.append('  missed: '+str(r['missed'])[:500])
    elif isinstance(r,dict) and 'findings' in r:
        brief.append('## '+str(label)+': '+str(len(r['findings']))+' findings')
open(sys.argv[2],'w',encoding='utf-8').write('\n'.join(full))
print('\n'.join(brief))
print('keys of first row:', list(rows[0].keys()) if rows else None, len(rows))
" "$D/journal.jsonl" "$OUT" 2>&1 | cut -c1-560; ls -la "$OUT" | cut -c1-120; date -u +"%H:%M:%S"

